import React, { useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useUser } from '@clerk/clerk-react';

const RedirectToUserProfile: React.FC = () => {
  const navigate = useNavigate();
  const { isLoaded, isSignedIn, user } = useUser();

  useEffect(() => {
    // Wait until the user object is loaded
    if (isLoaded && isSignedIn && user) {
      const isVerified = user.emailAddresses[0]?.verification?.status === 'verified';

      if (isVerified) {
        // If email is verified, redirect to the user profile
        console.log('RedirectToUserProfile: email verified, navigating to /user-profile');
        navigate('/user-profile', { replace: true });
      } else {
        // If email is not verified, redirect to the login page for verification
        console.log('RedirectToUserProfile: email not verified, redirecting to /login');
        navigate('/login', { replace: true });
      }
    } else if (isLoaded && !isSignedIn) {
      // If loaded but not signed in, redirect to login
      console.log('RedirectToUserProfile: not signed in, redirecting to /login');
      navigate('/login', { replace: true });
    }
  }, [isLoaded, isSignedIn, user, navigate]);

  // Render a loading state while waiting for redirection
  return (
    <div style={{ 
      display: 'flex', 
      alignItems: 'center', 
      justifyContent: 'center', 
      minHeight: '40vh', 
      flexDirection: 'column', 
      gap: 16,
      padding: '2rem'
    }}>
      <div 
        className="loading-spinner" 
        style={{
          width: '32px',
          height: '32px',
          border: '3px solid #f3f3f3',
          borderTop: '3px solid #007bff',
          borderRadius: '50%',
          animation: 'spin 1s linear infinite'
        }}
      />
      <p style={{ fontSize: '16px', color: '#666', margin: 0, textAlign: 'center' }}>
        Checking verification status…
      </p>
      <style>{`
        @keyframes spin {
          0% { transform: rotate(0deg); }
          100% { transform: rotate(360deg); }
        }
      `}</style>
    </div>
  );
};

export default RedirectToUserProfile;
